$NODE = $(if ($TR) { [string]$PRM.testNode } else { [string]$PRM.nodeExe }); $NODELOG = Join-Path (Join-Path $PD 'logs') 'node.log'
$BUNDLE = $(if ($TR) { [string]$PRM.testBundle } else { 'C:\Program Files\Enclave\control\windows\node\host-admission.bundle.mjs' })
$GATEJS = Join-Path $Stage 'gate-proof.mjs'; $GATE_JS_SHA = '@GATE_JS_SHA@'
$AGENT_PAT = '*\control\windows\node\agent.mjs*'; $RUN_PAT = '*\Enclave\run-node.cmd*'
$HOLD_RX = '(?m)^set ENCLAVE_NETWORK_WALLET_HOLD=1\r?$'
$POLICY_RX = '(?im)^\s*set\s+"?ENCLAVE_PLATFORM_HOST_POLICY'      # any assignment of the policy or one of its _* settings
# the node's 5 public Base RPCs (= run-node.cmd line 5 = privacy-config.json chain.rpc since root's rpc-integrated cutover)
$RPC5 = @('https://base-rpc.publicnode.com', 'https://base.gateway.tenderly.co', 'https://base-public.nodies.app', 'https://base.drpc.org', 'https://mainnet.base.org')
