$CARRIERS = '{"importDir":"C:/ProgramData/Enclave/node/policy-import"}'
$CARRIER_LINE = 'set "ENCLAVE_PLATFORM_HOST_POLICY_CARRIERS=' + $CARRIERS + '"'
$BASE_OPTION = $(if ($OPTION -in 'PC', 'RC') { $OPTION.Substring(0, 1) } else { $OPTION })
$POLICY_LINES = $(if ($BASE_OPTION -eq 'P') { @('set ENCLAVE_PLATFORM_HOST_POLICY=production') }
                  elseif ($BASE_OPTION -eq 'R') { @('set ENCLAVE_PLATFORM_HOST_POLICY=production', ('set "ENCLAVE_PLATFORM_HOST_POLICY_RPCS=' + ($GATE_RPC4 -join ',') + '"')) } else { @() })
if ($OPTION -in 'PC', 'RC' -and $POLICY_LINES.Count) { $POLICY_LINES = @($POLICY_LINES) + @($CARRIER_LINE) }
$GATE_RPCS = $(if ($BASE_OPTION -eq 'R') { $GATE_RPC4 -join ',' } else { '' })
