# ---------------------------------------------------------------- new for this activation (reviewed below; not in the base)
# The node's channel document and the network's view of it: generation, freshness, applied, allows (ids only; never a binding)
function Channel {
  $d = $null; try { $d = [IO.File]::ReadAllText($WALLET) | ConvertFrom-Json } catch {}
  $s = Status; $w = $(if ($s) { $s.walletAdmission } else { $null })
  [ordered]@{ docGen = [string]$d.generation; docRunner = ([string]$d.runner -eq [string]$PRM.runner)
    docExpiresInMs = $(if ($d) { [int64]$d.expiresAt - (NowMs) } else { $null }); statusAgeMs = $(if ($s) { (NowMs) - [int64]$s.updatedAt } else { $null })
    gen = [string]$w.generation; runner = ([string]$w.runner -eq [string]$PRM.runner); fresh = ($w.fresh -eq $true); applied = ($w.applied -eq $true)
    errorNull = ($null -eq $w.error); allows = @($w.allows | Where-Object { $_ } | ForEach-Object { [string]$_ }) } }
# enforced: THIS runner's document of generation $gen is fresh (<= 31 s), the network's status is fresh (< 5 s) and applies exactly
# it (fresh, applied, no error), and (with $ids) every id is allowed
function Enforced($c, $gen, $ids) {
  if (-not $c -or $c.docGen -notmatch '^[0-9a-f]{32}$' -or ($gen -and $c.docGen -ne $gen) -or -not $c.docRunner) { return $false }
  if ($null -eq $c.docExpiresInMs -or $c.docExpiresInMs -le 0 -or $c.docExpiresInMs -gt 31000) { return $false }
  if ($null -eq $c.statusAgeMs -or $c.statusAgeMs -lt 0 -or $c.statusAgeMs -ge 5000) { return $false }
  if ($c.gen -ne $c.docGen -or -not $c.runner -or -not $c.fresh -or -not $c.applied -or -not $c.errorNull) { return $false }
  foreach ($i in @($ids)) { if ($c.allows -notcontains [string]$i) { return $false } }
  return $true }
function EgressIds { try { @(([IO.File]::ReadAllText((Join-Path $STATE 'egress-routes.json')) | ConvertFrom-Json).apps.PSObject.Properties.Name) } catch { @() } }
# the gate's persisted state (measured gate persist: ONLY a known refusal is ever kept) -> $null (absent, or this host without a
# refusal) or why. Any knownRefusal is an EXPLICIT platform decision: never answered by turning the gate OFF.
function PersistedRefusal {
  if (-not (Test-Path -LiteralPath $ADMISSION)) { return $null }
  try { $a = [IO.File]::ReadAllText($ADMISSION) | ConvertFrom-Json } catch { return 'unreadable platform-host-admission.json' }
  if ([string]$a.hostId -cne [string]$PRM.runner) { return 'platform-host-admission.json names another host' }
  if ($null -ne $a.knownRefusal) { return 'knownRefusal ' + [string]$a.knownRefusal.status }
  return $null }
function PolicyNamed($p) { try { [regex]::Matches([IO.File]::ReadAllText($p), $POLICY_RX).Count } catch { -1 } }
# the node's records (id, status, walletHeld) for the post-check, through the base's bounded reader
function HostHeld([double]$limitSec = 10) {
  if ($TR) { $h = Invoke-RestMethod -UseBasicParsing -TimeoutSec 5 -Uri 'http://127.0.0.1:9600/v1/host/state'; return @($h.deployments | ForEach-Object { [ordered]@{id=$_.id;status=$_.status;walletHeld=($_.walletHeld -eq $true)} }) }
  @(Query { $h = Invoke-RestMethod -UseBasicParsing -TimeoutSec 5 -Uri 'http://127.0.0.1:9600/v1/host/state'
    @($h.deployments | ForEach-Object { [ordered]@{id=$_.id;status=$_.status;walletHeld=($_.walletHeld -eq $true)} }) } $limitSec) }
# THE GATE PROOF: the staged gate-proof.mjs (sha pinned) fed on stdin to the pinned node.exe, importing the INSTALLED bundle (sha
# pinned), with the exact environment the activation appends. Bounded child: killed at its budget and its exit confirmed; read-only
# (public chain reads; stateDir null). -> verdict ADMISSIBLE | NOT_ADMISSIBLE | REFUSED | UNKNOWN (+ categories, never secrets)
function GateProof([double]$limitSec = 60) {
  $ms = [int][math]::Floor(1000 * (Lim ([math]::Min(60, $limitSec))))
  if ($ms -lt 10000) { return [ordered]@{ verdict = 'UNKNOWN'; why = 'not enough time for the bounded gate proof' } }
  $jsb = [IO.File]::ReadAllBytes($GATEJS)
  if ((ShaBytes $jsb) -ne $GATE_JS_SHA) { return [ordered]@{ verdict = 'REFUSED'; why = 'the staged gate proof is not the pinned bytes' } }
  if ((Sha $BUNDLE) -ne [string]$PRM.bundleSha) { return [ordered]@{ verdict = 'REFUSED'; why = 'the installed host-admission bundle is not the pinned bytes' } }
  $si = New-Object Diagnostics.ProcessStartInfo; $si.FileName = $NODE; $si.Arguments = '--input-type=module'
  $si.UseShellExecute = $false; $si.CreateNoWindow = $true; $si.RedirectStandardInput = $true; $si.RedirectStandardOutput = $true; $si.RedirectStandardError = $true
  foreach ($kv in @(@('GATE_BUNDLE', $BUNDLE), @('GATE_HOST', [string]$PRM.runner), @('GATE_ENDPOINT', [string]$PRM.endpoint), @('GATE_POLICY', 'production'), @('GATE_RPCS', $GATE_RPCS), @('GATE_CARRIERS', $GATE_CARRIERS), @('GATE_OPTION', $OPTION))) { $si.EnvironmentVariables[$kv[0]] = [string]$kv[1] }
  $p = New-Object Diagnostics.Process; $p.StartInfo = $si; $sw = [Diagnostics.Stopwatch]::StartNew()
  $started = $false; $exited = $false; $res = $null; $why = $null
  try {
    $started = $p.Start()
    $so = $p.StandardOutput.ReadToEndAsync(); $se = $p.StandardError.ReadToEndAsync()
    $p.StandardInput.Write([Text.Encoding]::ASCII.GetString($jsb)); $p.StandardInput.Close()
    $exited = $p.WaitForExit([int][math]::Max(0, $ms - 3000 - $sw.ElapsedMilliseconds))
    if (-not $exited) { $why = 'the gate proof did not finish inside its budget' }
    elseif (-not $so.Wait(2000)) { $why = 'the gate proof output did not arrive' }
    else { $line = @(([string]$so.Result -split "`n") | Where-Object { $_.Trim().StartsWith('{') } | Select-Object -Last 1)
           if ($line.Count) { $res = $line[0] | ConvertFrom-Json } else { $why = 'the gate proof printed no JSON' } }
  } catch { $why = 'the gate proof could not run' }
  finally {
    if ($started -and -not $p.HasExited) { try { $p.Kill() } catch {}; $exited = $p.WaitForExit(3000) } elseif ($started) { $exited = $true }
    $p.Dispose() }
  if ($started -and -not $exited) { $script:QueryCleanupFailed = $true; $why = 'the gate proof child exit is unconfirmed' }
  if ($why) { return [ordered]@{ verdict = 'UNKNOWN'; why = $why; elapsedMs = $sw.ElapsedMilliseconds } }
  return [ordered]@{ verdict = [string]$res.verdict; why = [string]$res.why; status = [string]$res.gate.status; serving = ($res.gate.serving -eq $true)
    anchor = [string]$res.gate.anchor; block = [string]$res.gate.block; idMatchesEndpoint = ($res.idMatchesEndpoint -eq $true)
    registryActive = ($res.registry.active -eq $true); endpointMatches = ($res.registry.endpointMatches -eq $true); operator = [string]$res.registry.operator
    rpcHosts = @($res.config.rpcHosts); minAgree = $res.config.minAgree; mirrors = $res.config.mirrors; relayPolicy = [string]$res.relayPolicy; elapsedMs = $sw.ElapsedMilliseconds } }
# the node's new channel: a generation never seen in this run, applied by the network (fresh status of THIS runner)
function NewChannel($limitSec) {
  $lim = (Get-Date).AddSeconds((Lim $limitSec)); $gen = $null
  while ((Get-Date) -lt $lim) {
    try { $gen = [string]([IO.File]::ReadAllText($WALLET) | ConvertFrom-Json).generation } catch { $gen = $null }
    if ($gen -and $script:Gens -notcontains $gen -and (FreshStatus 3 0 'enforcing' $gen)) { $script:Gens += $gen; return $gen }
    Start-Sleep -Seconds 1 }
  return $null }
# node.log COUNTS since the pinned offset (base LogFrom): the gate's own lines, the channel's, and retirements of the EXPECTED ids
# (by id prefix: "0x38f368d6 isolated domain retired") apart from other ids'. LogFrom's counts live in an [ordered] dictionary, whose keys are
# CASE-INSENSITIVE: "is not serving" and "is NOT serving" would be ONE key (the second count overwriting the first), so the onChange
# pattern is keyed without the "[host-policy] " prefix (the regex itself stays case-sensitive)
$LOGPATS = @('[host-policy] this host is ADMITTED', '[host-policy] this host is not serving', 'this host is NOT serving:',
             'isolation spawned', 'wallet hold channel OFF', 'wallet hold channel NOT written', 'written EMPTY', 'isolated domain retired')
function LogCounts($offset) {
  $pats = @($LOGPATS) + @($PRM.expectedIds | ForEach-Object { ([string]$_).Substring(0, 10) + ' isolated domain retired' })
  $l = LogFrom $offset $pats; $exp = 0; foreach ($i in $PRM.expectedIds) { $exp += [int]$l[([string]$i).Substring(0, 10) + ' isolated domain retired'] }
  [ordered]@{ admitted = $l['[host-policy] this host is ADMITTED']; notServing = $l['[host-policy] this host is not serving']; notServingChange = $l['this host is NOT serving:']
    spawned = $l['isolation spawned']; channelOff = $l['wallet hold channel OFF']; channelNotWritten = $l['wallet hold channel NOT written']; channelStarted = $l['written EMPTY']
    retiredExpected = $exp; retiredOther = [int]$l['isolated domain retired'] - $exp; rotated = [bool]$l.rotated; error = $l.error } }
# THE coordinator's one revert (base Revert 496-529, node-only): node proven stopped -> node-config.local.cmd restored -> node
# started -> its new channel applied. A persisted EXPLICIT platform refusal is never reverted to OFF (RECOVERY_REQUIRED).
function Revert($why) {
  $script:Fwd = $false
  $script:RevertState = 'started'
  $x = [ordered]@{ step = 'revert'; why = $why; leaseLeft = (LeaseLeft) }
  $q = NodeProcs
  $stopped = ($q.cmd.Count -eq 0 -and $q.agent.Count -eq 0)
  if ($stopped) { $script:LastStopProofAt = Now }
  else {
    $x.stop = $(if ($q.cmd.Count -eq 1 -and $q.agent.Count -eq 1 -and $q.agent[0].parent -eq $q.cmd[0].pid) { StopNode $q.cmd[0] $q.agent[0] } else { 'the node processes are not one identifiable cmd+agent' })
    $stopped = $x.stop -eq 'stopped'
  }
  if (-not $stopped) { Recovery "the node could not be proven stopped ($($x.stop)); NO config was touched by the revert" $x }
  $x.stopProofAt = $script:LastStopProofAt
  $x.persisted = PersistedRefusal
  if ($x.persisted) { Recovery "the platform host policy persisted an explicit refusal ($($x.persisted)): turning the gate OFF would bypass the admin decision, so the policy line is KEPT and the node stays STOPPED; root/admin decide" $x }
  $x.local = RestoreOne 'local'
  if ($x.local -notin 'restored', 'already before' -or (Sha $LOCAL) -ne $before.local.before) {
    Recovery "node-config.local.cmd was not restored ($($x.local)); the node stays STOPPED" $x }
  if ((Sha $RUNNODE) -ne [string]$PRM.runNodeSha -or (Sha $NODECFG) -ne [string]$PRM.nodeConfigSha -or (Sha $CFG) -ne [string]$PRM.cfgSha -or -not (NodeStopped)) {
    Recovery 'run-node.cmd, node-config.cmd, privacy-config.json or the node changed during the run; node-config.local.cmd IS restored; the node is NOT started by this run' $x }
  $nn = StartNode 150; $x.nodeUp = [bool]$nn; $x.agent = $nn.agent
  if (-not $nn) { Recovery 'node-config.local.cmd IS restored, but the started node did not answer with a ready lease pass' $x }
  # the wallet hold is preserved: the restarted node runs a NEW generation that the network applies
  $x.channelGeneration = NewChannel 60; $x.channelApplied = [bool]$x.channelGeneration
  $script:RevertState = 'complete'
  return $x }
function Rolled($r, $tag, $text) {   # the final line of a completed revert
  $r.identityUnchanged = Identity $r; $r.privacyUnchanged = PrivacyPinned; $r.log = LogCounts $logOffset
  $ok = $r.identityUnchanged -and $r.privacyUnchanged -and $r.channelApplied
  Final $(if ($ok) { "${tag}: $text" } else { "${tag}_CHECK: $text, but a post-check failed (identity, privacy agent or channel): see fields" }) $r }
function PrivacyPinned { try { $pp = @(Privacy); $pp.Count -eq 1 -and $pp[0].pid -eq [int]$PRM.privacy.pid -and $pp[0].start -eq (Iso $PRM.privacy.start) } catch { $false } }

# a terminating error still goes through the SAME coordinator (base trap 537-557, node-only)
trap {
  $script:Fwd = $false
  $x = [ordered]@{ phase = $phase; error = $_.Exception.Message }
  if ($script:TaskMutationUnknown) { Recovery 'task request outcome unknown; no automatic retry or config rollback; inspect actual task/process state' $x }
  if ($script:RevertState -eq 'complete') { $x.final = "ROLLED_BACK_CHECK: the revert completed (node-config.local.cmd restored, node answered) but a later check failed ($($x.error)); no second revert; root decides"; Log $x; exit 1 }
  if ($script:RevertState) { Recovery "the revert itself failed ($($x.error)); no second automatic revert; inspect the actual node and config state" $x }
  if ($phase -in 'pins', 'verified') { $x.final = "CRASHED in phase ${phase}: no fallback ($(if ($phase -eq 'pins') { 'nothing was changed' } else { 'the new node was already verified' })); root decides"; Log $x; exit 1 }
  try {
    if ($phase -eq 'stopped') {   # the node is stopped and no config was touched: the pinned state, proven, then started
      $x.unchanged = ((Sha $LOCAL) -eq [string]$PRM.localSha -and (Sha $CFG) -eq [string]$PRM.cfgSha -and (Sha $RUNNODE) -eq [string]$PRM.runNodeSha -and (Sha $NODECFG) -eq [string]$PRM.nodeConfigSha)
      if (-not ($x.unchanged -and (NodeStopped))) { Recovery 'crash with the node stopped; a config is not the pinned one, so the node is NOT started' $x }
      $x.nodeUp = [bool](StartNode 150); if (-not $x.nodeUp) { Recovery 'crash with the node stopped and nothing else changed; the restarted node did not answer' $x }
      $x.channelGeneration = NewChannel 60
      Final "CRASHED_RESTORED: crash in phase $phase before any config change; the pinned state verified and the node started (channel applied: $([bool]$x.channelGeneration))" $x }
    $r = Revert "crash in phase $phase"; $r.error = $x.error
    Rolled $r 'ROLLED_BACK_AFTER_CRASH' "crash in phase $phase; node-config.local.cmd restored exactly, node started, its new channel applied"
  } catch { $x.taskCommand = $script:LastTaskCommand
    $x.final = $(if ($script:RevertState -eq 'complete') { "ROLLED_BACK_AFTER_CRASH_CHECK: the revert completed, but a later check failed ($($_.Exception.Message)); root decides" }
                 else { "RECOVERY_REQUIRED: the fallback itself failed ($($_.Exception.Message)); see the steps" }); Log $x; exit 1 } }

# ---------------------------------------------------------------- pins (both modes; nothing changes before 'stop-node')
$lock = Join-Path $Stage ("$Mode-$Run.lock")
try { $fs = [IO.File]::Open($lock, 'CreateNew', 'Write'); $fs.Close() } catch { Log ([ordered]@{ step = 'lock'; decision = 'REFUSED: this run id already ran (lock exists)' }); exit 0 }
$o = [ordered]@{ step = 'pins'; mode = $Mode; runner = [string]$PRM.runner; option = $OPTION }
$why = @()
if ($OPTION -notin 'P', 'R', 'PC', 'RC' -or $POLICY_LINES.Count -lt 1) { $why += 'the params name no pinned policy option (P, R, PC or RC)' }
foreach ($f in $PRM.files) { if ((Sha ([string]$f.path)) -ne [string]$f.sha) { $why += "file not as pinned: $($f.path)" } }
$np = NodeProcs; $o.node = $np
if ($np.cmd.Count -ne 1 -or $np.agent.Count -ne 1 -or $np.cmd[0].pid -ne [int]$PRM.node.cmdPid -or $np.cmd[0].start -ne (Iso $PRM.node.cmdStart) -or
    $np.agent[0].pid -ne [int]$PRM.node.agentPid -or $np.agent[0].start -ne (Iso $PRM.node.agentStart) -or $np.agent[0].parent -ne $np.cmd[0].pid) { $why += 'the node cmd/agent are not the pinned identities' }
$mg = Manager; $o.manager = $mg; if (-not (Known $mg) -or $mg -ne [string]$PRM.manager) { $why += 'the manager is unavailable or not the pinned PID+start' }
$pa = @(Privacy); $o.privacy = $pa; if ($pa.Count -ne 1 -or $pa[0].pid -ne [int]$PRM.privacy.pid -or $pa[0].start -ne (Iso $PRM.privacy.start)) { $why += 'the privacy agent is not the pinned PID+start' }
$vms0 = Vms; $hv0 = HyperV; $others0 = Others
$o.vmCount = $(if (Known $vms0) { @($vms0 -split ',' | Where-Object { $_ }).Count } else { -1 }); $o.hypervCount = $(if (Known $hv0) { @($hv0 -split ',' | Where-Object { $_ }).Count } else { -1 })
if (-not (Known $vms0) -or $vms0 -ne [string]$PRM.vms) { $why += 'the manager instance set is unavailable or not the preflight set' }
if (-not (Known $hv0) -or $hv0 -ne [string]$PRM.hyperv) { $why += 'the Hyper-V VM set (Get-VM) is unavailable or not the preflight set' }
$logOffset = $(try { (Get-Item -LiteralPath $NODELOG).Length } catch { 0 }); $o.nodeLogOffset = $logOffset
$uv = $null; try { $uv = UpdateState 10 } catch { if ($script:QueryCleanupFailed) { throw } }
$o.updateTask = $uv; $ur = UpdateDecision $uv; if ($ur) { $why += $ur }
# N3 (base): the node-config.local.cmd temp is created in the data dir: new files there may inherit READ for SYSTEM/Administrators only
$pr = Readers $PD; $o.programDataFileInheritReaders = $pr.fileInheritReaders
if (@($pr.fileInheritReaders | Where-Object { $ADMIN_SIDS -notcontains $_ }).Count) { $why += 'new files in the Enclave data directory inherit READ for more than SYSTEM/Administrators (N3)' }
# LEASE DEADLINE (base): every expected id a RUNNING record of THIS node with a numeric leaseUntil, read now from the node itself
$lp = $PRM.lease; $o.lease = $null
if (-not $lp -or [int]$lp.marginSec -le 0 -or [int]$lp.revertSec -le 0 -or [int]$lp.forwardMinSec -le 0 -or [int]$lp.startNodeSec -le 0) { $why += 'the lease budget (lease.marginSec/revertSec/forwardMinSec/startNodeSec) is missing from the pinned params' }
else {
  $hs = $null; try { $hs = HostState 10 } catch {}
  $by = @{}; foreach ($d in @($hs.deployments)) { if ($d) { $by[([string]$d.id).ToLower()] = $d } }
  $ends = @(); $bad = @()
  foreach ($i in @($PRM.expectedIds)) { $d = $by[([string]$i).ToLower()]; $v = $d.leaseUntil
    if ($d -and [string]$d.status -eq 'running' -and ($v -is [int] -or $v -is [long] -or $v -is [double] -or $v -is [decimal])) { $ends += [pscustomobject]@{ id = [string]$i; end = [int64]$v } } else { $bad += [string]$i } }
  if (-not $hs) { $o.lease = 'unreadable'; if ($Mode -eq 'activate') { $why += 'the node lease state (127.0.0.1:9600/v1/host/state) is unreadable: the lease deadline is unknown' } }
  elseif ($bad.Count) { $o.lease = [ordered]@{ notRunningOrNoLease = $bad }; if ($Mode -eq 'activate') { $why += "expected ids without a running record and a numeric leaseUntil: $($bad -join ',')" } }
  elseif (-not @($PRM.expectedIds).Count) { $why += 'no expected deployments' }
  else { $first = @($ends | Sort-Object end)[0]; $LeaseEnd = $first.end
    $o.lease = [ordered]@{ firstId = $first.id; firstEnd = $LeaseEnd; secLeft = $LeaseEnd - (NowS); forwardSec = (LeaseLeft); marginSec = [int]$lp.marginSec; revertSec = [int]$lp.revertSec; forwardMinSec = [int]$lp.forwardMinSec; startNodeSec = [int]$lp.startNodeSec }
    if ($Mode -eq 'activate' -and (LeaseLeft) -lt [int]$lp.forwardMinSec) {
      $why += "lease deadline: the first lease ($($first.id.Substring(0, 10))) ends in $($LeaseEnd - (NowS)) s, this activation needs >= $([int]$lp.forwardMinSec + [int]$lp.revertSec + [int]$lp.marginSec) s (forward + revert + margin): run it right after the next renewals" } } }
# Recoverable (lease-critical) path of the node-only revert: initial snapshot 15 + StopNode 135 + final stopped snapshot 15 + node
# readiness 150 = 315; + 25 for the persisted-refusal read, ONE CAS restore and its hash reads, journal lines = 340. The revert's
# channel wait (<= 60 s) runs after the node answers (renewing again) and is reserved from the global bound only.
# Forward (lease-critical): StopNode 135 + backup/CAS append 10 + node readiness startNodeSec 150 + channel 30 = 325.
if ($lp -and [int]$lp.revertSec -lt 340) { $why += 'revert budget is shorter than the 340-second bounded node-only revert allowance' }
if ($lp -and ((Left) - [int]$lp.revertSec - 60) -lt [int]$lp.forwardMinSec) { $why += 'global deadline leaves insufficient forward time after reserving recovery (+60 s revert channel wait)' }
if ((Sha $LOCAL) -ne [string]$PRM.localSha) { $why += 'node-config.local.cmd is not the pinned sha' }
if ((Sha $CFG) -ne [string]$PRM.cfgSha) { $why += 'privacy-config.json is not the pinned sha' }
if ((Sha $RUNNODE) -ne [string]$PRM.runNodeSha) { $why += 'run-node.cmd is not the pinned sha' }
if ((Sha $NODECFG) -ne [string]$PRM.nodeConfigSha) { $why += 'node-config.cmd is not the pinned sha' }
if (-not $TR -and (-not $PRM.nodeExe -or -not $PRM.nodeSha -or (Sha $NODE) -ne [string]$PRM.nodeSha)) { $why += 'the node.exe for the gate proof is not the pinned (root-proven) binary' }
if ((Sha $BUNDLE) -ne [string]$PRM.bundleSha) { $why += 'the installed host-admission bundle is not the pinned bytes' }
# THE WALLET HOLD IS ALREADY ENFORCED (this coordinator's precondition; the base cutover REFUSES this state): exactly one hold flag,
# the network applies THIS runner's fresh generation with every expected id allowed and routed; the channel file writers unchanged
$lt = $(try { [IO.File]::ReadAllText($LOCAL) } catch { '' }); $o.holdFlags = [regex]::Matches($lt, $HOLD_RX).Count
if ($o.holdFlags -ne 1) { $why += 'node-config.local.cmd does not carry exactly one wallet hold flag line' }
$c0 = Channel; $script:G0 = $c0.docGen; $script:Gens = @($c0.docGen); $o.channel = [ordered]@{ generation = $c0.docGen; allows = $c0.allows.Count; docExpiresInMs = $c0.docExpiresInMs; statusAgeMs = $c0.statusAgeMs }
if (-not (Enforced $c0 $null @($PRM.expectedIds))) { $why += 'the wallet hold is not enforced as pinned (fresh document of this runner, applied by a fresh network status, every expected id allowed)' }
$eg0 = EgressIds; $o.egressApps = $eg0.Count; if (@($PRM.expectedIds | Where-Object { $eg0 -notcontains [string]$_ }).Count) { $why += 'an expected id has no egress route' }
$wr0 = $(try { Writers $WALLET } catch { $null }); if (-not $wr0 -or @($wr0.writers | Where-Object { $ADMIN_SIDS -notcontains $_ }).Count -or $ADMIN_SIDS -notcontains $wr0.owner) { $why += 'the wallet channel file is writable by more than SYSTEM/Administrators' }
$o.persisted = PersistedRefusal
if ($Mode -eq 'activate') {
  foreach ($p in $LOCAL, $NODECFG, $RUNNODE) { $n = PolicyNamed $p; if ($n -ne 0) { $why += "$(Split-Path -Leaf $p) already assigns ENCLAVE_PLATFORM_HOST_POLICY* ($n) or is unreadable: root decides, nothing is appended over it" } }
  if ($o.persisted) { $why += "the node's gate state already holds a platform refusal ($($o.persisted)): the activation would start a refused node" }
  # node-config.local.cmd is the only file this run writes: an auto-inherited DACL (D:AI / D:PAI), the base's proven round-trip form
  $df = [regex]::Match([string](Get-Acl -LiteralPath $LOCAL).Sddl, 'D:([A-Z]*)\(').Groups[1].Value
  if ($df -notmatch 'AI') { $why += "node-config.local.cmd has a DACL that is not auto-inherited (D:$df): the exact ACL round-trip would refuse; root fixes that ACL first" }
} else {
  $b = $PRM.before.local
  if ((Sha ([string]$b.backup)) -ne [string]$b.before) { $why += 'the node-config.local.cmd backup is not its before sha' }
  if ((Sha $LOCAL) -ne [string]$b.after) { $why += 'node-config.local.cmd is not the activation''s journaled after sha (already restored, or changed since): root decides' }
  if ($o.persisted) { $why += "an explicit platform refusal is persisted ($($o.persisted)): turning the gate OFF would bypass the admin decision; no rollback" }
}
if ($why.Count) { Final ('REFUSED: ' + ($why -join '; ')) $o }
Log $o
$before = @{ local = @{ before = [string]$PRM.localSha; after = ''; backup = '' } }
if ($Mode -eq 'rollback') { $b = $PRM.before.local; $before.local = @{ before = [string]$b.before; after = [string]$b.after; backup = [string]$b.backup } }

# ---------------------------------------------------------------- activate: prepare in memory, then PROVE admission (nothing stopped)
$prepared = $null
if ($Mode -eq 'activate') {
  $lb = [IO.File]::ReadAllBytes($LOCAL)
  # BYTE-level append (base flag step): the file's existing bytes are never re-encoded
  $sep = $(if ($lb.Length -eq 0 -or ($lb.Length -ge 2 -and $lb[$lb.Length - 2] -eq 13 -and $lb[$lb.Length - 1] -eq 10)) { '' } else { "`r`n" })
  $add = [Text.Encoding]::ASCII.GetBytes($sep + (($POLICY_LINES | ForEach-Object { $_ + "`r`n" }) -join ''))
  $prepared = New-Object byte[] ($lb.Length + $add.Length); [Array]::Copy($lb, $prepared, $lb.Length); [Array]::Copy($add, 0, $prepared, $lb.Length, $add.Length)
  $gp = GateProof 60
  Log ([ordered]@{ step = 'gate'; proof = $gp; preparedSha = (ShaBytes $prepared); addedBytes = $add.Length; lines = $POLICY_LINES.Count })
  if ($gp.verdict -ne 'ADMISSIBLE') { Final "REFUSED: the installed gate did not prove admission of this host with the exact configuration ($($gp.verdict): $($gp.why)); nothing was stopped or changed" ([ordered]@{}) }
}

# ---------------------------------------------------------------- stop the node (both modes)
$Fwd = ($Mode -eq 'activate')
$st = StopNode ([ordered]@{ pid = [int]$PRM.node.cmdPid; start = (Iso $PRM.node.cmdStart) }) ([ordered]@{ pid = [int]$PRM.node.agentPid; start = (Iso $PRM.node.agentStart) })
Log ([ordered]@{ step = 'stop-node'; decision = $st; nodeStopped = ($st -eq 'stopped'); stopProofAt = $script:LastStopProofAt })
if ($st -like 'REFUSED:*') { Final $st ([ordered]@{ leaseFirstEnd = $LeaseEnd; forwardLeft = (ForwardLeft) }) }
if ($st -eq 'identity changed; nothing stopped') { Final 'REFUSED: the node identity changed before the stop; nothing was stopped or changed' ([ordered]@{}) }
if ($st -ne 'stopped') { Recovery "the node could not be proven stopped before any change ($st); NO config changed; nothing started" ([ordered]@{}) }
$phase = 'stopped'

if ($Mode -eq 'rollback') {
  $phase = 'configs'; $r = Revert 'explicit rollback'
  $phase = 'verified'
  Rolled $r 'ROLLED_BACK' 'node-config.local.cmd restored to the exact before-bytes (platform host policy OFF as before), node started, its new channel applied' }

# ---------------------------------------------------------------- activate: the one config write (node proven stopped)
$phase = 'configs'
NeedForward
PrivDir
# r5: the backup is created EXCLUSIVELY inside the verified private directory (never over an existing name), then written
$before.local.backup = Join-Path $PRIV "node-config.local.cmd.before-$Run"
$bfs = [IO.File]::Open($before.local.backup, [IO.FileMode]::CreateNew, [IO.FileAccess]::Write); try { $bfs.Write($lb, 0, $lb.Length) } finally { $bfs.Close() }
Log ([ordered]@{ step = 'backups'; local = (Sha $before.local.backup); localBackup = $before.local.backup })
if ((Sha $before.local.backup) -ne $before.local.before) { $r = Revert 'the backup is not the pinned before sha'; Rolled $r 'ROLLED_BACK_R0' 'the backup did not match; nothing was written; node started' }
try {
  $w = CasWrite $LOCAL $before.local.before $prepared; $before.local.after = $w.after
  Log ([ordered]@{ step = 'policy'; after = $w.after; aclKept = $w.aclKept; asPrepared = ($w.after -eq (ShaBytes $prepared)) })
  if (-not $w.aclKept) { throw 'the node-config ACL changed' }
  if ($w.after -ne (ShaBytes $prepared)) { throw 'node-config.local.cmd is not the prepared bytes after the write' }
} catch {
  $err = $_.Exception.Message
  if (-not $before.local.after -and (Sha $LOCAL) -ne $before.local.before) { $before.local.after = 'unknown-write' }
  $r = Revert "config write failed: $err"; $r.error = $err
  Rolled $r 'ROLLED_BACK_R0' 'the config write failed; node-config.local.cmd restored exactly, node started (policy OFF as before)' }

# ---------------------------------------------------------------- start the node; its gate must ADMIT (READY) and its channel apply
if ((ForwardLeft) -lt [int]$PRM.lease.startNodeSec) {
  $r = Revert "LEASE/GLOBAL: $([math]::Floor((ForwardLeft))) s of forward time left before the lease deadline (< lease.startNodeSec)"
  Rolled $r 'ROLLED_BACK_LEASE' 'the lease deadline left no time to start and verify the new node; node-config.local.cmd restored exactly, node started (policy OFF as before)' }
$phase = 'node-started'
$nn = StartNode ([int]$PRM.lease.startNodeSec)
$gen = $(if ($nn) { NewChannel 30 } else { $null })
$lc = LogCounts $logOffset; $pr1 = PersistedRefusal
Log ([ordered]@{ step = 'start-node'; nodeUp = [bool]$nn; agent = $nn.agent; channelGeneration = $gen; applied = [bool]$gen; leaseLeft = (LeaseLeft); log = $lc; persisted = $pr1 })
if ($pr1) {   # the admin's EXPLICIT decision about this host, read by the new gate: never answered by turning the gate OFF
  $phase = 'verified'; $Fwd = $false
  $x = [ordered]@{ step = 'policy-refused'; persisted = $pr1; nodeUp = [bool]$nn; nodeRunning = $(try { -not (NodeStopped) } catch { 'unknown' }); localAsWritten = ((Sha $LOCAL) -eq $before.local.after) }
  $x.identityUnchanged = Identity $x
  Final 'REFUSED_BY_POLICY: the platform host policy explicitly refuses this host (persisted by the new gate); the policy line is KEPT and the node runs fail-closed (no new work, no app traffic, no renewals); NO rollback, which would bypass the admin decision; root/admin decide' $x }
if (-not $nn -or -not $gen) {
  $r = Revert "R2: nodeUp=$([bool]$nn) channel=$([bool]$gen) (not READY: the gate did not admit or a lease pass failed; or the network did not apply the new channel)"
  Rolled $r 'ROLLED_BACK_R2' 'the new node was not READY with an applied channel; the revert stopped it, restored node-config.local.cmd exactly and started the node (policy OFF as before)' }

# ---------------------------------------------------------------- observe the re-grants (no rollback from here: root decides)
$phase = 'verified'; $Fwd = $false
$want = @($PRM.expectedIds); $lim = (Get-Date).AddSeconds([math]::Min(240, (Left))); $missing = $want
while ($missing.Count -and (Get-Date) -lt $lim) { $c = Channel; $missing = @($want | Where-Object { -not ($c.gen -eq $gen -and $c.fresh -and $c.applied -and $c.allows -contains [string]$_) }); if ($missing.Count) { Start-Sleep 2 } }
$wr = Writers $WALLET; $eg = EgressIds; $rec = @(); try { $rec = HostHeld 10 } catch { if ($script:QueryCleanupFailed) { throw } }
$post = [ordered]@{ step = 'post'; missingGrants = $missing; egressMissing = @($want | Where-Object { $eg -notcontains [string]$_ }); walletWriters = $wr.writers; walletOwner = $wr.owner
  recordsNotRunning = @($want | Where-Object { $i = [string]$_; @($rec | Where-Object { [string]$_.id -eq $i -and [string]$_.status -eq 'running' -and -not $_.walletHeld }).Count -ne 1 })
  log = (LogCounts $logOffset); persisted = (PersistedRefusal); channelGeneration = $gen; oldGeneration = $script:G0 }
$post.identityUnchanged = Identity $post
$post.privacyUnchanged = PrivacyPinned
$post.localAsWritten = ((Sha $LOCAL) -eq $before.local.after)
$post.othersAsPinned = ((Sha $RUNNODE) -eq [string]$PRM.runNodeSha -and (Sha $NODECFG) -eq [string]$PRM.nodeConfigSha -and (Sha $CFG) -eq [string]$PRM.cfgSha)
$post.walletAclOk = (@($wr.writers | Where-Object { $ADMIN_SIDS -notcontains $_ }).Count -eq 0) -and ($ADMIN_SIDS -contains $wr.owner)
$l = $post.log
$clean = $post.identityUnchanged -and $post.privacyUnchanged -and $post.localAsWritten -and $post.othersAsPinned -and $post.walletAclOk -and -not $post.persisted -and
         -not $l.error -and -not $l.rotated -and [int]$l.admitted -ge 1 -and [int]$l.notServing -eq 0 -and [int]$l.notServingChange -eq 0 -and [int]$l.spawned -eq 0 -and
         [int]$l.channelOff -eq 0 -and [int]$l.channelNotWritten -eq 0 -and [int]$l.channelStarted -ge 1 -and [int]$l.retiredExpected -eq 0 -and
         -not $post.egressMissing.Count -and -not $post.recordsNotRunning.Count
Final $(if ($clean -and -not $missing.Count) { 'DONE: platform host policy ON and ADMITTING this host in the new node (READY lease pass, "[host-policy] this host is ADMITTED"); wallet hold kept (new generation applied, every expected id re-granted and routed); privacy agent, manager, Hyper-V VMs, other tasks and every other config unchanged' }
        elseif ($clean) { 'DONE_PARTIAL: as DONE, but some ids not re-granted yet (held on UNKNOWN, or slow): see missingGrants' }
        else { 'DONE_CHECK: the gate admitted (READY) and the channel applied, but a post-check failed (identity, privacy agent, configs, node.log counts, records, routes or channel-file ACL): see post; root decides, nothing automatic' }) $post
